def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    foreground = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The patterned color is the non-background color occurring in alternating runs.
    colors = {v for row in grid for v in row}
    bg = min(colors, key=lambda v: sum(row.count(v) for row in grid))
    foreground = next(v for v in colors if v != bg)
    for r in range(h):
        for c in range(w - 2):
            if grid[r][c] == foreground and grid[r][c + 2] == foreground and grid[r][c + 1] == bg:
                out[r][c + 1] = 2
    return out
